/* Token inspector.
 *
 * Renders the real Qwen3-4B tokenization of a compound, with and without a
 * leading space, next to the activation feature 118230 gave it. Data comes
 * from tokens.js, generated by scripts/build_page_data.py.
 */

(function () {
  "use strict";

  const data = window.TOKEN_DATA;
  if (!data) return;

  const picker = document.getElementById("picker");
  const readout = document.getElementById("readout");
  if (!picker || !readout) return;

  // Scale the meter against the strongest activation in the set, so the bars
  // are comparable to each other rather than to an arbitrary ceiling.
  const maxActivation = data.words.reduce(function (max, word) {
    return Math.max(max, word.activation || 0);
  }, 0);

  const GROUP_LABELS = {
    true_single: "true single-token",
    conditional_single: "conditional single-token",
    true_multi: "true multi-token",
    unlisted: "not in the word list",
  };

  const VERDICTS = {
    true_single: "One token either way — the tokenizer never had to choose.",
    conditional_single:
      "One token only when a space comes first. The model meets this word in two different shapes.",
    true_multi: "Several tokens either way — consistently assembled from parts.",
    unlisted: "Shown as an example; not part of the measured set.",
  };

  /** Build the coloured chips for one tokenization. */
  function renderTokens(tokens) {
    const list = document.createElement("div");
    list.className = "tokens";

    tokens.forEach(function (token) {
      const chip = document.createElement("span");
      chip.className = "tok";
      // Draw the leading space instead of letting it collapse — it is the
      // independent variable of the whole experiment.
      if (token.startsWith(" ")) {
        const ws = document.createElement("span");
        ws.className = "ws";
        ws.textContent = "␣";
        chip.appendChild(ws);
        chip.appendChild(document.createTextNode(token.slice(1)));
      } else {
        chip.textContent = token;
      }
      list.appendChild(chip);
    });

    return list;
  }

  function renderRow(label, tokens) {
    const row = document.createElement("div");
    row.className = "split";

    const name = document.createElement("div");
    name.className = "split-label";
    name.textContent = label;

    const body = document.createElement("div");
    body.appendChild(renderTokens(tokens));

    const count = document.createElement("div");
    count.className = "count";
    count.textContent = tokens.length === 1 ? "1 token" : tokens.length + " tokens";
    body.appendChild(count);

    row.appendChild(name);
    row.appendChild(body);
    return row;
  }

  function renderVerdict(entry) {
    const row = document.createElement("div");
    row.className = "verdict";

    const name = document.createElement("div");
    name.className = "split-label";
    name.textContent = "Activation";

    const body = document.createElement("div");

    if (entry.activation === null || entry.activation === undefined) {
      const text = document.createElement("div");
      text.className = "meter-value";
      text.textContent = "not measured — " + VERDICTS[entry.group];
      body.appendChild(text);
    } else {
      const meter = document.createElement("div");
      meter.className = "meter";
      const fill = document.createElement("div");
      fill.className = "meter-fill";
      fill.style.width = "0%";
      meter.appendChild(fill);
      body.appendChild(meter);

      const text = document.createElement("div");
      text.className = "meter-value";
      const value = entry.activation.toFixed(4).replace(/0+$/, "").replace(/\.$/, "");
      text.innerHTML =
        "<b>" +
        (entry.activation === 0 ? "0" : value) +
        "</b> · " +
        GROUP_LABELS[entry.group] +
        " · " +
        VERDICTS[entry.group];
      body.appendChild(text);

      // Let the bar animate in from zero on the next frame.
      requestAnimationFrame(function () {
        const pct = maxActivation ? (entry.activation / maxActivation) * 100 : 0;
        fill.style.width = Math.max(pct, entry.activation > 0 ? 1.5 : 0) + "%";
      });
    }

    row.appendChild(name);
    row.appendChild(body);
    return row;
  }

  function show(entry) {
    readout.innerHTML = "";
    readout.appendChild(renderRow("bare", entry.bare));
    readout.appendChild(renderRow("with space", entry.spaced));
    readout.appendChild(renderVerdict(entry));
  }

  function select(entry, button) {
    picker.querySelectorAll(".pick").forEach(function (other) {
      other.setAttribute("aria-pressed", String(other === button));
    });
    show(entry);
  }

  // Order the chips so the three groups are visibly interleaved rather than
  // sorted into blocks — the point is that group membership is not guessable
  // from the word.
  const byGroup = { true_single: [], conditional_single: [], true_multi: [] };
  data.words.forEach(function (entry) {
    if (byGroup[entry.group]) byGroup[entry.group].push(entry);
  });

  const ordered = [];
  const keys = Object.keys(byGroup);
  let index = 0;
  while (ordered.length < data.words.length) {
    let added = false;
    keys.forEach(function (key) {
      if (byGroup[key][index]) {
        ordered.push(byGroup[key][index]);
        added = true;
      }
    });
    if (!added) break;
    index += 1;
  }

  ordered.forEach(function (entry) {
    const button = document.createElement("button");
    button.className = "pick";
    button.type = "button";
    button.setAttribute("aria-pressed", "false");

    const dot = document.createElement("span");
    dot.className = "dot dot-" + entry.group;
    button.appendChild(dot);
    button.appendChild(document.createTextNode(entry.word));

    button.addEventListener("click", function () {
      select(entry, button);
    });

    picker.appendChild(button);
  });

  // Open on a word that shows the phenomenon and has a measured activation.
  const first =
    ordered.find(function (entry) {
      return entry.word === "waterfall";
    }) || ordered[0];

  if (first) {
    const buttons = picker.querySelectorAll(".pick");
    const match = Array.prototype.find.call(buttons, function (button) {
      return button.textContent.trim() === first.word;
    });
    select(first, match);
  }
})();
